const STORAGE_KEY = "todo-items-v1";

class TodoStore {
  constructor(storage = window.localStorage) {
    this.storage = storage;
    this.items = this.load();
    this.undoStack = [];
    this.listeners = new Set();
  }

  load() {
    try {
